sql_query:
SELECT "Primary endpoint"
FROM clinical_trials
WHERE "Cancer type" = 'Non-Small Cell Lung' AND "Included in MA" = 'Yes' AND "Name of ICI" = 'Nivolumab';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Primary endpoint" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Non-Small Cell Lung' AND "Included in MA" = 'Yes' AND "Name of ICI" = 'Nivolumab'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_endpoint_components(source_value) AS "components"
FROM base;
